CREATE VIEW `v_active_whatsapp_endpoints` AS select "organization_channel_endpoints"."id", "organization_channels"."organizationId", "channel_endpoints"."id", "channel_endpoints"."number", "channel_endpoints"."ownerKind", "organization_channel_endpoints"."isPrimary", "organization_channels"."channelId", "organization_integrations"."id", "organization_integrations"."status", "organization_integrations"."credentials", "organization_integrations"."config" from "organization_channel_endpoints" inner join "organization_channels" on "organization_channel_endpoints"."organizationChannelId" = "organization_channels"."id" inner join "channel_endpoints" on "organization_channel_endpoints"."endpointId" = "channel_endpoints"."id" left join "organization_integrations" on "organization_channels"."integrationId" = "organization_integrations"."id" where (("organization_channel_endpoints"."status" = 'active') and ("organization_channels"."isEnabled" = 1) and ("channel_endpoints"."status" = 'active') and ("channel_endpoints"."provider" = 'whatsapp_cloud') and (("organization_channel_endpoints"."deleted_at" is null)) and (("organization_channels"."deleted_at" is null)) and (("channel_endpoints"."deleted_at" is null)));